// Logos (PNG) incrustados: en Vercel la carpeta public no está en el sistema de archivos de las funciones.
const LOGOS_PNG_BASE64: Record<string, string> = {
  laufit:
    '',
  fitfactory:
    '',
}

/** Logo del cliente activo (TENANT) para los comprobantes; sin TENANT conocido se usa el de LAUFIT. */
export function logoPngBase64(tenantId: string): string {
  return LOGOS_PNG_BASE64[tenantId] ?? LOGOS_PNG_BASE64.laufit
}
